paragraphs = []
for heading, body in sections:
    paragraphs.append((heading, True))
    if heading.startswith("Решение"):
        first, rest = body.split("\n", 1)
        second, third = rest.split("\n", 1)
        paragraphs.extend([(first + "\n" + second, False), (third, False)])
    elif heading.startswith("Бизнес-модель"):
        first, second = body.split("\n", 1)
        paragraphs.extend([(first, False), (second, False)])
    else:
        paragraphs.append((body, False))
    if heading.startswith("Конкурентные"):
        paragraphs.append(("", False))

assert len(paragraphs) == 21, len(paragraphs)

with opc.edit_docx(str(WORK)) as doc:
    for i, (value, is_heading) in enumerate(paragraphs):
        p = doc.paragraphs[i]
        p.text = value
        for run in p.runs:
            run.font.name = "Times New Roman"
            run.font.size = Pt(14)
            run.bold = is_heading

word_count = sum(len(value.replace("—", " ").split()) for value, _ in paragraphs)
print(f"Слов: {word_count}")
print(OUT / "Текст выступления FridgeChef.docx")
